from __future__ import annotations

import asyncio
import json
import os
import threading
import time
from dataclasses import dataclass
from typing import Any

from apex_backend.ros_names import public_ros_name, ros_name

try:
    from rclpy.qos import qos_profile_sensor_data
except ModuleNotFoundError:  # pragma: no cover - exercised by local smoke tests without ROS.
    qos_profile_sensor_data = 10

try:
    from rosidl_runtime_py.convert import message_to_ordereddict
    from rosidl_runtime_py.utilities import get_message
except ModuleNotFoundError:  # pragma: no cover - exercised by local smoke tests without ROS.
    def message_to_ordereddict(msg: Any) -> dict[str, Any]:
        return dict(getattr(msg, "__dict__", {}))

    def get_message(_: str) -> Any:
        return object


DEFAULT_TOPIC_WHITELIST = [
    "base_teleop",
    "info/arm_state",
    "info/base_teleop/active_mode",
    "info/base_local_state",
    "info/robot_state",
    "info/vr_connected",
    "joint_states",
    "move/ManualMoveCmd",
    "move/State",
    "move/state",
    "odometry",
    "target_pose",
]
DEFAULT_TOPIC_FPS = 30.0
PER_TOPIC_FPS: dict[str, float] = {}


def _csv_env(name: str, default: list[str]) -> list[str]:
    raw = os.environ.get(name, "")
    values = [item.strip() for item in raw.split(",") if item.strip()]
    return values or list(default)


@dataclass(eq=False)
class TopicBridgeClient:
    loop: asyncio.AbstractEventLoop
    queue: asyncio.Queue[str]

    def enqueue(self, text: str) -> None:
        def put_latest() -> None:
            if self.queue.full():
                try:
                    self.queue.get_nowait()
                except asyncio.QueueEmpty:
                    pass
            self.queue.put_nowait(text)

        self.loop.call_soon_threadsafe(put_latest)


@dataclass
class _TopicChannel:
    min_interval: float
    next_send_time: float = 0.0
    pending_message: tuple[str, Any, int] | None = None
    flush_timer: threading.Timer | None = None


class TopicBridge:
    def __init__(
        self,
        node: Any,
        topic_whitelist: list[str] | None = None,
        default_topic_fps: float = DEFAULT_TOPIC_FPS,
        robot_info_topic: str = "info/robot_info",
    ) -> None:
        self._node = node
        configured_topics = topic_whitelist or _csv_env("APEX_TOPIC_WHITELIST", DEFAULT_TOPIC_WHITELIST)
        self._topic_whitelist = {ros_name(topic) for topic in configured_topics}
        self._robot_info_topic = ros_name(os.environ.get("APEX_ROBOT_INFO_TOPIC", robot_info_topic))
        self._default_min_interval = 1.0 / default_topic_fps if default_topic_fps > 0 else 0.0
        self._lock = threading.RLock()
        self._clients: set[TopicBridgeClient] = set()
        self._channels: dict[str, _TopicChannel] = {}
        self._topic_subscriptions: dict[str, Any] = {}
        self._unknown_topics_logged: set[str] = set()
        self._latest_robot_info: dict[str, Any] = {
            "type": "robot_info",
            "topic": public_ros_name(self._robot_info_topic),
            "stamp_ns": None,
            "robot_type": "unknown",
            "controller_version": None,
            "controller_version_text": "",
            "base_model": None,
            "arm_model": None,
            "stand_shoulder_width_m": None,
            "stand_height_m": None,
            "stand_options": ["legacy", "new", "m6stand", "m6litestand", "user"],
        }
        self._robot_info_subscription: Any = None
        self._discovery_timer: Any = None
        self.start()

    def start(self) -> None:
        self._start_robot_info_subscription()
        self._discovery_timer = self._node.create_timer(1.0, self.refresh_subscriptions)
        self._log_info(
            f"Topic WebSocket bridge mounted at /ws/v1/topics, whitelist size: {len(self._topic_whitelist)}"
        )

    def stop(self) -> None:
        with self._lock:
            for channel in self._channels.values():
                if channel.flush_timer is not None:
                    channel.flush_timer.cancel()
            self._clients.clear()

        for handle in [self._discovery_timer, self._robot_info_subscription, *self._topic_subscriptions.values()]:
            if handle is None:
                continue
            destroy = getattr(self._node, "destroy_timer", None)
            if handle is self._discovery_timer and destroy is not None:
                destroy(handle)
                continue
            destroy_subscription = getattr(self._node, "destroy_subscription", None)
            if destroy_subscription is not None:
                destroy_subscription(handle)

    def add_client(self) -> TopicBridgeClient:
        client = TopicBridgeClient(loop=asyncio.get_running_loop(), queue=asyncio.Queue(maxsize=100))
        with self._lock:
            self._clients.add(client)
            robot_info = dict(self._latest_robot_info)
        client.enqueue(json.dumps(robot_info, ensure_ascii=False))
        return client

    def remove_client(self, client: TopicBridgeClient) -> None:
        with self._lock:
            self._clients.discard(client)

    def robot_info_snapshot(self) -> dict[str, Any]:
        with self._lock:
            payload = dict(self._latest_robot_info)
        return {
            "robot_type": payload.get("robot_type", "unknown"),
            "controller_version": payload.get("controller_version"),
            "controller_version_text": payload.get("controller_version_text") or "unknown",
            "base_model": payload.get("base_model"),
            "arm_model": payload.get("arm_model"),
            "stand_shoulder_width_m": payload.get("stand_shoulder_width_m"),
            "stand_height_m": payload.get("stand_height_m"),
            "stand_options": payload.get(
                "stand_options", ["legacy", "new", "m6stand", "m6litestand", "user"]
            ),
            "stamp_ns": payload.get("stamp_ns"),
            "age_sec": None,
            "received": payload.get("robot_type") not in (None, "unknown"),
        }

    def refresh_subscriptions(self) -> None:
        current_topic_types: dict[str, list[str]] = {
            topic_name: type_list for topic_name, type_list in self._node.get_topic_names_and_types()
        }

        for topic in self._topic_whitelist:
            if topic in self._topic_subscriptions:
                continue

            types = current_topic_types.get(topic)
            if not types:
                if topic not in self._unknown_topics_logged:
                    self._log_warning(f"Whitelist topic not discovered yet: {topic}")
                    self._unknown_topics_logged.add(topic)
                continue

            if len(types) != 1:
                self._log_error(f"Skip topic {topic}: expected one message type, got {types}")
                continue

            type_name = types[0]
            try:
                msg_cls = get_message(type_name)
            except Exception as exc:
                self._log_error(f"Failed to resolve message type {type_name} for {topic}: {exc}")
                continue

            self._topic_subscriptions[topic] = self._node.create_subscription(
                msg_cls,
                topic,
                lambda msg, t=topic, tn=type_name: self._topic_callback(t, tn, msg),
                qos_profile_sensor_data,
            )
            self._log_info(f"Subscribed whitelist topic: {topic} [{type_name}]")

    def _start_robot_info_subscription(self) -> None:
        try:
            from marvin_msgs.msg import RobotInfo
        except (ImportError, ModuleNotFoundError):
            self._log_warning("marvin_msgs/msg/RobotInfo is unavailable; /ws/v1/topics will use unknown robot_info")
            return

        self._robot_info_subscription = self._node.create_subscription(
            RobotInfo,
            self._robot_info_topic,
            self._robot_info_callback,
            qos_profile_sensor_data,
        )

    def _robot_info_callback(self, msg: Any) -> None:
        base_model = getattr(msg, "base_model", None)
        payload = {
            "type": "robot_info",
            "topic": public_ros_name(self._robot_info_topic),
            "stamp_ns": self._node.get_clock().now().nanoseconds,
            "robot_type": msg.robot_type,
            "controller_version": int(msg.controller_version),
            "controller_version_text": msg.controller_version_text,
            "base_model": base_model,
            "arm_model": getattr(msg, "arm_model", None),
            "stand_shoulder_width_m": getattr(msg, "stand_shoulder_width_m", None),
            "stand_height_m": getattr(msg, "stand_height_m", None),
            "stand_options": ["legacy", "new", "m6stand", "m6litestand", "user"],
        }
        with self._lock:
            self._latest_robot_info = payload
        self._broadcast(json.dumps(payload, ensure_ascii=False))

    def _topic_callback(self, topic_name: str, type_name: str, msg: Any) -> None:
        # Avoid converting and JSON-encoding high-rate ROS messages when no
        # browser is consuming the topic bridge.  When clients are connected,
        # rate-limit the raw message first and serialize only the frame that is
        # actually sent (or the latest pending frame for the next interval).
        with self._lock:
            if not self._clients:
                return
        stamp_ns = self._node.get_clock().now().nanoseconds
        self._enqueue_message(topic_name, type_name, msg, stamp_ns)

    def _serialize_message(
        self,
        topic_name: str,
        type_name: str,
        msg: Any,
        stamp_ns: int,
    ) -> str:
        payload = {
            "topic": public_ros_name(topic_name),
            "type": type_name,
            "stamp_ns": stamp_ns,
            "msg": message_to_ordereddict(msg),
        }
        return json.dumps(payload, ensure_ascii=False)

    def _channel_for(self, topic: str) -> _TopicChannel:
        channel = self._channels.get(topic)
        if channel is None:
            fps = PER_TOPIC_FPS.get(topic)
            min_interval = (1.0 / fps) if fps and fps > 0 else self._default_min_interval
            channel = _TopicChannel(min_interval=min_interval)
            self._channels[topic] = channel
        return channel

    def _enqueue_message(
        self,
        topic: str,
        type_name: str,
        msg: Any,
        stamp_ns: int,
    ) -> None:
        now = time.monotonic()
        send_message: tuple[str, Any, int] | None = None
        with self._lock:
            channel = self._channel_for(topic)
            if now >= channel.next_send_time:
                channel.next_send_time = now + channel.min_interval
                send_message = (type_name, msg, stamp_ns)
            else:
                channel.pending_message = (type_name, msg, stamp_ns)
                if channel.flush_timer is None:
                    delay = max(0.0, channel.next_send_time - now)
                    channel.flush_timer = threading.Timer(delay, self._flush_pending, args=(topic,))
                    channel.flush_timer.daemon = True
                    channel.flush_timer.start()

        if send_message is not None:
            pending_type, pending_msg, pending_stamp_ns = send_message
            self._broadcast(
                self._serialize_message(
                    topic,
                    pending_type,
                    pending_msg,
                    pending_stamp_ns,
                )
            )

    def _flush_pending(self, topic: str) -> None:
        with self._lock:
            channel = self._channels.get(topic)
            if channel is None:
                return
            pending_message = channel.pending_message
            channel.pending_message = None
            channel.flush_timer = None
            channel.next_send_time = time.monotonic() + channel.min_interval

        if pending_message is not None:
            type_name, msg, stamp_ns = pending_message
            self._broadcast(
                self._serialize_message(topic, type_name, msg, stamp_ns)
            )

    def _broadcast(self, text: str) -> None:
        with self._lock:
            clients = list(self._clients)
        for client in clients:
            client.enqueue(text)

    def _log_info(self, message: str) -> None:
        self._node.get_logger().info(message)

    def _log_warning(self, message: str) -> None:
        self._node.get_logger().warning(message)

    def _log_error(self, message: str) -> None:
        self._node.get_logger().error(message)
